-- Phase 32: every view, download and print of an invoice (SPEC core 10, "View and print
-- tracking"). A PRINT row carries its copy number: 0 is the original, n is "Copy of Original (n)";
-- the partial unique index lets an invoice have each number once.
-- Generated by drizzle-kit; the triggers at the end are hand-added: the log is append-only
-- (UPDATE, DELETE and TRUNCATE are refused for every role).
CREATE TABLE "invoice_access_log" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"invoice_id" uuid NOT NULL,
	"user_id" uuid NOT NULL,
	"actor_role" "user_role" NOT NULL,
	"action" text NOT NULL,
	"copy_number" integer,
	"occurred_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
	"ip_address" "inet",
	"user_agent" text,
	CONSTRAINT "invoice_access_log_action_check" CHECK ("invoice_access_log"."action" IN ('VIEW', 'DOWNLOAD', 'PRINT')),
	CONSTRAINT "invoice_access_log_copy_number_check" CHECK (("invoice_access_log"."action" = 'PRINT') = ("invoice_access_log"."copy_number" IS NOT NULL)
            AND ("invoice_access_log"."copy_number" IS NULL OR "invoice_access_log"."copy_number" >= 0))
);
